extern "C" {
    fn isatty(fd: i32) -> i32;
}

fn libc_isatty(fd: i32) -> i32 {
    unsafe { isatty(fd) }
}

fn cmd_init(args: &[String]) {
    // Check if stdin is a TTY
    if !is_stdin_tty() {
        print_error("IO error: not a terminal");
        process::exit(1);
    }

    // Parse args
    let mut grammar_path: Option<PathBuf> = None;
    let mut update = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-u" | "--update" => {
                update = true;
            }
            "-p" | "--grammar-path" => {
                i += 1;
                if i < args.len() {
                    grammar_path = Some(PathBuf::from(&args[i]));
                }
            }
            _ => {}
        }
        i += 1;
    }

    let path = grammar_path.unwrap_or_else(|| env::current_dir().unwrap());

    // Check if tree-sitter.json already exists
    let ts_json_path = path.join("tree-sitter.json");

    if !update && ts_json_path.exists() {
        // Read existing config and offer to update
        run_init_interactive(&path, true);
    } else if !update {
        run_init_interactive(&path, false);
    } else {
        // Update mode - still need tree-sitter.json
