fn get_config_dir() -> PathBuf {
    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        PathBuf::from(xdg)
    } else {
        let home = env::var("HOME").unwrap_or_else(|_| "/".to_string());
        PathBuf::from(home).join(".config")
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let program_name = Path::new(&args[0])
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("tree-sitter")
        .to_string();

    if args.len() < 2 {
        print_main_help(&program_name);
        process::exit(0);
    }

    let subcmd = args[1].as_str();
    let subargs = &args[2..];

    // Check for --help/-h in subargs (but not for 'query' which requires positional arg first)
    let has_help = subargs.iter().any(|a| a == "--help" || a == "-h");

    match subcmd {
        "--help" | "-h" => {
            print_main_help(&program_name);
            process::exit(0);
        }
        "--version" | "-V" => {
            println!("tree-sitter {}", VERSION);
            process::exit(0);
        }
        "init-config" => {
            if has_help {
                print_init_config_help(&program_name);
                process::exit(0);
            }
            cmd_init_config();
        }
        "init" => {
            if has_help {
                print_init_help(&program_name);
                process::exit(0);
            }
            cmd_init(subargs);
        }
        "generate" => {
            if has_help {
                print_generate_help(&program_name);
                process::exit(0);
            }
            cmd_generate(subargs);
        }
        "build" => {
            if has_help {
                print_build_help(&program_name);
                process::exit(0);
            }
            cmd_build(subargs);
        }
        "parse" => {
            if has_help {
                print_parse_help(&program_name);
                process::exit(0);
            }
            cmd_parse(subargs);
        }
        "test" => {
            if has_help {
                print_test_help(&program_name);
                process::exit(0);
            }
            cmd_test(subargs);
        }
        "version" => {
            if has_help {
                print_version_help(&program_name);
                process::exit(0);
            }
            cmd_version(subargs);
        }
        "fuzz" => {
            if has_help {
                print_fuzz_help(&program_name);
                process::exit(0);
            }
            cmd_fuzz(subargs);
        }
        "query" => {
            if has_help {
                print_query_help(&program_name);
                process::exit(0);
            }
            cmd_query(subargs, &program_name);
        }
        "highlight" => {
            if has_help {
                print_highlight_help(&program_name);
                process::exit(0);
            }
            cmd_highlight(subargs);
        }
        "tags" => {
            if has_help {
                print_tags_help(&program_name);
                process::exit(0);
            }
            cmd_tags(subargs);
        }
        "playground" => {
            if has_help {
                print_playground_help(&program_name);
                process::exit(0);
            }
            cmd_playground(subargs);
        }
        "dump-languages" => {
            if has_help {
                print_dump_languages_help(&program_name);
                process::exit(0);
            }
            cmd_dump_languages(subargs);
        }
        "complete" => {
            if has_help {
                print_complete_help(&program_name);
                process::exit(0);
            }
            cmd_complete(subargs, &program_name);
        }
        cmd => {
            eprintln!("error: unrecognized subcommand '{}'", cmd);
            eprintln!();
            eprintln!("Usage: {} <COMMAND>", program_name);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
    }
}

