// ===== Command implementations =====

fn cmd_init_config() {
    let config_dir = get_config_dir().join("tree-sitter");
    let config_file = config_dir.join("config.json");

    if config_file.exists() {
        eprint_error(&format!(
            "Remove your existing config file first: {}",
            config_file.display()
        ));
        process::exit(1);
    }

    if let Err(e) = fs::create_dir_all(&config_dir) {
        eprint_error(&format!("{}", e));
        process::exit(1);
    }

    let home = env::var("HOME").unwrap_or_else(|_| "/home/user".to_string());
    let config_content = format!(
        "{{\n  \"parser-directories\": [\n    \"{home}/github\",\n    \"{home}/src\",\n    \"{home}/source\",\n    \"{home}/projects\",\n    \"{home}/dev\",\n    \"{home}/git\"\n  ],\n  \"theme\": {{\n    \"attribute\": {{\n      \"color\": 124,\n      \"italic\": true\n    }},\n    \"comment\": {{\n      \"color\": 245,\n      \"italic\": true\n    }},\n    \"constant\": 94,\n    \"constant.builtin\": {{\n      \"bold\": true,\n      \"color\": 94\n    }},\n    \"constructor\": 136,\n    \"embedded\": null,\n    \"function\": 26,\n    \"function.builtin\": {{\n      \"bold\": true,\n      \"color\": 26\n    }},\n    \"keyword\": 56,\n    \"module\": 136,\n    \"number\": {{\n      \"bold\": true,\n      \"color\": 94\n    }},\n    \"operator\": {{\n      \"bold\": true,\n      \"color\": 239\n    }},\n    \"property\": 124,\n    \"property.builtin\": {{\n      \"bold\": true,\n      \"color\": 124\n    }},\n    \"punctuation\": 239,\n    \"punctuation.bracket\": 239,\n    \"punctuation.delimiter\": 239,\n    \"punctuation.special\": 239,\n    \"string\": 28,\n    \"string.special\": 30,\n    \"tag\": 18,\n    \"type\": 23,\n    \"type.builtin\": {{\n      \"bold\": true,\n      \"color\": 23\n    }},\n    \"variable\": 252,\n    \"variable.builtin\": {{\n      \"bold\": true,\n      \"color\": 252\n    }},\n    \"variable.parameter\": {{\n      \"color\": 252,\n      \"underline\": true\n    }}\n  }}\n}}",
        home = home
    );

    if let Err(e) = fs::write(&config_file, &config_content) {
        eprint_error(&format!("{}", e));
        process::exit(1);
    }

    eprintln!("Saved initial configuration to {}", config_file.display());
}

fn get_grammar_path(args: &[String]) -> PathBuf {
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-p" | "--grammar-path" => {
                if i + 1 < args.len() {
                    return PathBuf::from(&args[i + 1]);
                }
            }
            s if s.starts_with("--grammar-path=") => {
                return PathBuf::from(s.strip_prefix("--grammar-path=").unwrap());
            }
            _ => {}
        }
        i += 1;
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn get_config_path(args: &[String]) -> Option<PathBuf> {
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--config-path" => {
                if i + 1 < args.len() {
                    return Some(PathBuf::from(&args[i + 1]));
                }
            }
            s if s.starts_with("--config-path=") => {
                return Some(PathBuf::from(s.strip_prefix("--config-path=").unwrap()));
            }
            _ => {}
        }
        i += 1;
    }
    None
}

fn cmd_generate(args: &[String]) {
    // Find grammar path
    let mut grammar_path: Option<PathBuf> = None;
    let mut js_runtime = "node".to_string();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--js-runtime" => {
                i += 1;
                if i < args.len() {
                    js_runtime = args[i].clone();
                }
            }
            s if s.starts_with("--js-runtime=") => {
                js_runtime = s.strip_prefix("--js-runtime=").unwrap().to_string();
            }
            s if !s.starts_with('-') => {
                if grammar_path.is_none() {
                    grammar_path = Some(PathBuf::from(s));
                }
            }
            _ => {}
        }
        i += 1;
    }

    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let grammar_js = match &grammar_path {
        Some(p) => p.clone(),
        None => cwd.join("grammar.js"),
    };

    let abs_grammar_js = if grammar_js.is_absolute() {
        grammar_js.clone()
    } else {
        cwd.join(&grammar_js)
    };

    if !abs_grammar_js.exists() {
        eprint_error_caused(
            "Error when generating parser",
            &format!(
                "Failed to load grammar.js -- No such file or directory (os error 2) ({})",
                abs_grammar_js.display()
            ),
        );
        process::exit(1);
    }

    // Try to run the JS runtime
    let runtime_cmd = if js_runtime == "native" {
        // Native mode - not supported in our implementation
        eprint_error_caused(
            "Error when generating parser",
            "Failed to load grammar.js -- native runtime not supported",
        );
        process::exit(1);
    } else {
        js_runtime.as_str()
    };

    // Try to run node/runtime
    match process::Command::new(runtime_cmd).arg("--version").output() {
        Ok(_) => {
            // Runtime exists, but we can't actually run tree-sitter generation
            eprint_error_caused(
                "Error when generating parser",
                &format!(
                    "Failed to load grammar.js -- tree-sitter generation not supported"
                ),
            );
            process::exit(1);
        }
        Err(e) => {
            eprint_error_caused(
                "Error when generating parser",
                &format!(
                    "Failed to load grammar.js -- Failed to run `{}` -- {}",
                    runtime_cmd,
                    e
                ),
            );
            process::exit(1);
        }
    }
}

fn cmd_build(args: &[String]) {
    let grammar_dir = if let Some(pos) = args.iter().position(|a| !a.starts_with('-')) {
        // Could be a positional argument
        let mut found = None;
        let mut i = 0;
        while i < args.len() {
            let a = &args[i];
            if a == "-o" || a == "--output" || a == "-w" || a == "--wasm" {
                if a == "-o" || a == "--output" { i += 1; }
            } else if !a.starts_with('-') {
                found = Some(PathBuf::from(a));
                break;
            }
            i += 1;
        }
        found.unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
    } else {
        env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    };

    let grammar_json = grammar_dir.join("src").join("grammar.json");
    let abs_grammar_json = if grammar_json.is_absolute() {
        grammar_json.clone()
    } else {
        env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(&grammar_json)
    };

    if !abs_grammar_json.exists() {
        eprint_error_caused(
            "Failed to compile parser",
            &format!(
                "No such file or directory (os error 2) ({})",
                abs_grammar_json.display()
            ),
        );
        process::exit(1);
    }

    // grammar.json exists - try to compile
    let parser_c = grammar_dir.join("src").join("parser.c");
    let abs_parser_c = if parser_c.is_absolute() {
        parser_c.clone()
    } else {
        env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(&parser_c)
    };

    if !abs_parser_c.exists() {
        eprint_error_caused(
            "Failed to compile parser",
            &format!(
                "No such file or directory (os error 2) ({})",
                abs_parser_c.display()
            ),
        );
        process::exit(1);
    }

    eprint_error_caused(
        "Failed to compile parser",
        "tree-sitter runtime not available",
    );
    process::exit(1);
}

fn parse_file_paths(args: &[String]) -> (Vec<PathBuf>, Option<PathBuf>, Option<String>, bool) {
    let mut paths = Vec::new();
    let mut paths_file: Option<PathBuf> = None;
    let mut scope: Option<String> = None;
    let mut has_positional = false;
    let mut i = 0;
    // Skip flags with values
    let skip_next: &[&str] = &[
        "--paths", "-p", "--grammar-path", "-l", "--lib-path", "--lang-name",
        "--scope", "-d", "--debug", "--timeout", "--edits", "--encoding",
        "--config-path", "-n", "--test-number", "--dot",
    ];
    while i < args.len() {
        let a = args[i].as_str();
        if a == "--paths" {
            i += 1;
            if i < args.len() {
                paths_file = Some(PathBuf::from(&args[i]));
            }
        } else if a == "--scope" {
            i += 1;
            if i < args.len() {
                scope = Some(args[i].clone());
            }
        } else if a.starts_with("--scope=") {
            scope = Some(a.strip_prefix("--scope=").unwrap().to_string());
        } else if skip_next.iter().any(|&s| a == s) {
            i += 1; // skip value
        } else if a.starts_with('-') {
            // other flags, ignore
        } else {
            paths.push(PathBuf::from(a));
            has_positional = true;
        }
        i += 1;
    }
    (paths, paths_file, scope, has_positional)
}

fn cmd_parse(args: &[String], _program_name: &str) {
    // Check for invalid flags first
    let known_flags: &[&str] = &[
        "--paths", "-p", "--grammar-path", "-l", "--lib-path", "--lang-name",
        "--scope", "-d", "--debug", "-0", "--debug-build", "-D", "--debug-graph",
        "--dot", "-x", "--xml", "-c", "--cst", "-s", "--stat", "--timeout",
        "-t", "--time", "-q", "--quiet", "--edits", "--encoding", "--open-log",
        "--json", "-j", "--json-summary", "--config-path", "-n", "--test-number",
        "-r", "--rebuild", "--no-ranges",
    ];

    let (paths, paths_file, scope, has_positional) = parse_file_paths(args);

    // Validate encoding
    for (i, a) in args.iter().enumerate() {
        if a == "--encoding" {
            if i + 1 < args.len() {
                let enc = args[i + 1].as_str();
                if enc != "utf8" && enc != "utf16-le" && enc != "utf16-be" {
                    eprintln!("error: invalid value '{}' for '--encoding <ENCODING>'", enc);
                    eprintln!("  [possible values: utf8, utf16-le, utf16-be]");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    process::exit(2);
                }
            }
        }
    }

    // Handle paths file
    if let Some(ref pf) = paths_file {
        if !pf.exists() {
            eprint_error_caused(
                &format!("Failed to read paths file {}", pf.display()),
                "No such file or directory (os error 2)",
            );
            process::exit(1);
        }
        // Read file and add paths
        let content = fs::read_to_string(pf).unwrap_or_default();
        let mut extra_paths: Vec<PathBuf> = content
            .lines()
            .filter(|l| !l.trim().is_empty())
            .map(PathBuf::from)
            .collect();

        let all_paths: Vec<PathBuf> = extra_paths;
        parse_files_with_scope(&all_paths, scope.as_deref(), true);
        return;
    }

    if paths.is_empty() {
        // Parse stdin
        println!(); // the leading newline
        parse_files_with_scope(&[], scope.as_deref(), false);
    } else {
        // Check if files exist
        let mut all_exist = true;
        for p in &paths {
            if !p.exists() {
                // Try glob matching
                all_exist = false;
                break;
            }
        }

        if !all_exist && paths.len() == 1 {
            // Check if it's a glob pattern
            let p = &paths[0];
            let path_str = p.to_string_lossy();
            if path_str.contains('*') || path_str.contains('?') || path_str.contains('[') {
                eprint_error("No files were found at or matched by the provided pathname/glob");
                process::exit(1);
            }
        }

        parse_files_with_scope(&paths, scope.as_deref(), paths.len() > 1);
    }
}

