fn cmd_playground(args: &[String]) {
    // Find grammar path
    let mut grammar_path: Option<PathBuf> = None;
    let mut export_path: Option<PathBuf> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--grammar-path" => {
                i += 1;
                if i < args.len() {
                    grammar_path = Some(PathBuf::from(&args[i]));
                }
            }
            "-e" | "--export" => {
                i += 1;
                if i < args.len() {
                    export_path = Some(PathBuf::from(&args[i]));
                }
            }
            _ => {}
        }
        i += 1;
    }

    let grammar_dir = grammar_path.unwrap_or_else(|| {
        env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    });

    let grammar_json = grammar_dir.join("src").join("grammar.json");
    let abs_grammar_json = if grammar_json.is_absolute() {
        grammar_json.clone()
    } else {
        env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(&grammar_json)
    };

