        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        process::exit(101);
    }

    // Look for wasm file
    let ts_json = grammar_dir.join("tree-sitter.json");
    let lang_name = if ts_json.exists() {
        read_grammar_name(&ts_json).unwrap_or_else(|| "unknown".to_string())
    } else {
        "unknown".to_string()
    };

    let wasm_file = format!("tree-sitter-{}.wasm", lang_name);
