fn extract_metadata_version(json: &str) -> Option<String> {
    // Find "metadata" section and then "version" inside it
    let meta_start = json.find("\"metadata\"")?;
    let after_meta = &json[meta_start..];
    // Find the next "version" after metadata
    let ver_start = after_meta.find("\"version\"")?;
    let after_ver = &after_meta[ver_start + "\"version\"".len()..];
    // Skip whitespace and colon
    let colon_pos = after_ver.find(':')?;
    let after_colon = &after_ver[colon_pos + 1..].trim_start();
    // Extract string value
    if after_colon.starts_with('"') {
        let end = after_colon[1..].find('"')?;
        Some(after_colon[1..end + 1].to_string())
    } else {
        None
    }
}

fn bump_version(version: &str, bump_type: &str) -> Option<String> {
    let parts: Vec<u64> = version.split('.').map(|p| p.parse().ok()).collect::<Option<Vec<_>>>()?;
    if parts.len() != 3 {
        return None;
    }
    match bump_type {
        "patch" => Some(format!("{}.{}.{}", parts[0], parts[1], parts[2] + 1)),
        "minor" => Some(format!("{}.{}.0", parts[0], parts[1] + 1)),
        "major" => Some(format!("{}.0.0", parts[0] + 1)),
        _ => None,
    }
}

fn version_lt(a: &str, b: &str) -> bool {
    let parse_ver = |s: &str| -> Option<(u64, u64, u64)> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 3 {
            return None;
        }
        let major = parts[0].parse::<u64>().ok()?;
        let minor = parts[1].parse::<u64>().ok()?;
        let patch = parts[2].parse::<u64>().ok()?;
        Some((major, minor, patch))
    };

    match (parse_ver(a), parse_ver(b)) {
        (Some(va), Some(vb)) => va < vb,
        _ => false,
    }
}

fn update_version_in_files(grammar_dir: &Path, old_ver: &str, new_ver: &str) {
    // Update tree-sitter.json metadata.version
    let ts_json_path = grammar_dir.join("tree-sitter.json");
    if ts_json_path.exists() {
        if let Ok(content) = fs::read_to_string(&ts_json_path) {
            // Update metadata version
            let new_content = replace_metadata_version(&content, old_ver, new_ver);
            let _ = fs::write(&ts_json_path, &new_content);
        }
    }

    // Update package.json "version": "x.y.z"
    let pkg_json = grammar_dir.join("package.json");
    if pkg_json.exists() {
        if let Ok(content) = fs::read_to_string(&pkg_json) {
            let new_content = replace_top_level_version(&content, old_ver, new_ver);
            let _ = fs::write(&pkg_json, &new_content);
        }
    }

    // Update CMakeLists.txt VERSION "x.y.z" in project()
    let cmake = grammar_dir.join("CMakeLists.txt");
    if cmake.exists() {
        if let Ok(content) = fs::read_to_string(&cmake) {
            let new_content = replace_cmake_version(&content, old_ver, new_ver);
            let _ = fs::write(&cmake, &new_content);
        }
    }

    // Update pyproject.toml version = "x.y.z"
    let pyproject = grammar_dir.join("pyproject.toml");
    if pyproject.exists() {
        if let Ok(content) = fs::read_to_string(&pyproject) {
            let new_content = replace_toml_version(&content, old_ver, new_ver);
            let _ = fs::write(&pyproject, &new_content);
        }
    }

    // Update Makefile VERSION := x.y.z
    let makefile = grammar_dir.join("Makefile");
    if makefile.exists() {
        if let Ok(content) = fs::read_to_string(&makefile) {
            let new_content = replace_makefile_version(&content, old_ver, new_ver);
            let _ = fs::write(&makefile, &new_content);
        }
    }
}

fn replace_metadata_version(json: &str, old: &str, new: &str) -> String {
    // Replace "version": "old" within "metadata" block
    // Strategy: find metadata block, then replace version within it
    if let Some(meta_start) = json.find("\"metadata\"") {
        let before_meta = &json[..meta_start];
        let in_and_after = &json[meta_start..];

        // Find the version within the metadata block
        if let Some(ver_pos) = in_and_after.find(&format!("\"version\": \"{}\"", old)) {
            let replace = format!("\"version\": \"{}\"", old);
            let with = format!("\"version\": \"{}\"", new);
            let new_in = format!("{}{}{}", 
                &in_and_after[..ver_pos],
                &with,
                &in_and_after[ver_pos + replace.len()..]);
            return format!("{}{}", before_meta, new_in);
        }
    }
    json.to_string()
}

fn replace_top_level_version(json: &str, old: &str, new: &str) -> String {
    // Find first "version": "old" in the JSON
    let search = format!("\"version\": \"{}\"", old);
    let replace = format!("\"version\": \"{}\"", new);

    if let Some(pos) = json.find(&search) {
        format!("{}{}{}", &json[..pos], replace, &json[pos + search.len()..])
    } else {
        // Try without spaces
        let search2 = format!("\"version\":\"{}\"", old);
        let replace2 = format!("\"version\":\"{}\"", new);
        if let Some(pos) = json.find(&search2) {
            format!("{}{}{}", &json[..pos], replace2, &json[pos + search2.len()..])
        } else {
            json.to_string()
        }
    }
}

fn replace_cmake_version(content: &str, old: &str, new: &str) -> String {
    let search = format!("VERSION \"{}\"", old);
    let replace = format!("VERSION \"{}\"", new);
    content.replacen(&search, &replace, 1)
}

fn replace_toml_version(content: &str, old: &str, new: &str) -> String {
    let search = format!("version = \"{}\"", old);
    let replace = format!("version = \"{}\"", new);
    // Only replace in [project] section, not in other sections
    // Simple approach: replace first occurrence
    content.replacen(&search, &replace, 1)
}

fn replace_makefile_version(content: &str, old: &str, new: &str) -> String {
    let search = format!("VERSION := {}", old);
    let replace = format!("VERSION := {}", new);
    content.replacen(&search, &replace, 1)
}

// Simple JSON string finder
fn json_find_string(json: &str, key: &str) -> Option<String> {
    let search = format!("\"{}\"", key);
    let pos = json.find(&search)?;
    let after = &json[pos + search.len()..];
    let colon = after.find(':')?;
    let after_colon = after[colon + 1..].trim_start();
    if after_colon.starts_with('"') {
        let end = after_colon[1..].find('"')?;
        Some(after_colon[1..end + 1].to_string())
    } else {
        None
    }
}

