        return None;
    }
    match bump_type {
        "patch" => Some(format!("{}.{}.{}", parts[0], parts[1], parts[2] + 1)),
        "minor" => Some(format!("{}.{}.0", parts[0], parts[1] + 1)),
        "major" => Some(format!("{}.0.0", parts[0] + 1)),
        _ => None,
    }
