// ===== Init command (interactive TUI) =====

fn cmd_init(args: &[String]) {
    if !is_tty(0) {
        eprint_error("IO error: not a terminal");
        process::exit(1);
    }

    let mut grammar_path: Option<PathBuf> = None;
    let mut update = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-u" | "--update" => {
                update = true;
            }
            "-p" | "--grammar-path" => {
                i += 1;
                if i < args.len() {
                    grammar_path = Some(PathBuf::from(&args[i]));
                }
            }
            s if s.starts_with("--grammar-path=") => {
                grammar_path = Some(PathBuf::from(s.strip_prefix("--grammar-path=").unwrap()));
            }
            _ => {}
        }
        i += 1;
    }

    let path = grammar_path.unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
    let ts_json_path = path.join("tree-sitter.json");

    if ts_json_path.exists() && !update {
        // Already initialized - do nothing
        return;
    }

    if update && !ts_json_path.exists() {
        eprint_error(&format!(
            "No such file or directory (os error 2) ({})",
            ts_json_path.display()
        ));
        process::exit(1);
    }

    if update {
        // Read existing config and regenerate files
        do_init_update(&path, &ts_json_path);
        return;
    }

    // Interactive prompts
    let config = run_init_prompts(&path);

    if let Some(cfg) = config {
        // Write tree-sitter.json
        write_grammar_files(&path, &cfg);
    }
}

#[derive(Default)]
struct GrammarConfig {
    name: String,
    camelcase: String,
    title: String,
    description: String,
    repository: String,
    funding: String,
    scope: String,
    file_types: Vec<String>,
    version: String,
    license: String,
    author_name: String,
    author_email: String,
    author_url: String,
    namespace: String,
    bindings_c: bool,
    bindings_go: bool,
    bindings_java: bool,
    bindings_node: bool,
    bindings_python: bool,
    bindings_rust: bool,
    bindings_swift: bool,
    bindings_zig: bool,
}

fn camelcase(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;
    for ch in s.chars() {
        if ch == '-' || ch == '_' {
            capitalize_next = true;
        } else if capitalize_next {
            result.extend(ch.to_uppercase());
            capitalize_next = false;
        } else {
            result.push(ch);
        }
    }
    result
}

fn run_init_prompts(path: &Path) -> Option<GrammarConfig> {
    use std::io::{BufRead, Write};

    let stdin = io::stdin();
    let stderr = io::stderr();

    let mut cfg = GrammarConfig::default();

    // Parser name
    cfg.name = prompt_text("Parser name", None)?;

    // CamelCase name
    let default_camel = camelcase(&cfg.name);
    cfg.camelcase = prompt_text_with_default("CamelCase name", &default_camel)?;

    // Title
    cfg.title = prompt_text_with_default("Title (human-readable name)", &cfg.camelcase.clone())?;

    // Description
    let default_desc = format!("{} grammar for tree-sitter", cfg.camelcase);
    cfg.description = prompt_text_with_default("Description", &default_desc)?;

    // Repository URL
    let default_repo = format!("https://github.com/tree-sitter/tree-sitter-{}", cfg.name);
    cfg.repository = prompt_text_with_default("Repository URL", &default_repo)?;

    // Funding URL
    cfg.funding = prompt_text_optional("Funding URL")?;

    // TextMate scope
    let default_scope = format!("source.{}", cfg.name);
    cfg.scope = prompt_text_with_default("TextMate scope", &default_scope)?;

    // File types
    let default_ft = cfg.name.clone();
    let ft_str = prompt_text_with_default("File types (space-separated)", &default_ft)?;
    cfg.file_types = ft_str.split_whitespace().map(|s| s.to_string()).collect();
    if cfg.file_types.is_empty() {
        cfg.file_types = vec![cfg.name.clone()];
    }

    // Version
