}

const TCSANOW: i32 = 0;

extern "C" {
    fn tcgetattr(fd: i32, termios: *mut libc_termios) -> i32;
    fn tcsetattr(fd: i32, action: i32, termios: *const libc_termios) -> i32;
    fn cfmakeraw(termios: *mut libc_termios);
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
}

fn libc_read(fd: i32, buf: *mut u8, count: usize) -> isize {
    unsafe { read(fd, buf, count) }
}

fn do_init_update(path: &Path, ts_json_path: &Path) {
    // Read existing config
    let content = match fs::read_to_string(ts_json_path) {
        Ok(c) => c,
        Err(e) => {
            eprint_error(&format!("{}", e));
            process::exit(1);
        }
    };

    // Parse the config
    let cfg = parse_ts_json(&content);
    if let Some(cfg) = cfg {
        // Regenerate files that might be outdated
        update_binding_files(path, &cfg);
    }
}

fn update_binding_files(path: &Path, cfg: &GrammarConfig) {
    // Regenerate binding files, reporting what's being replaced
    let files_to_update = get_updatable_files(path, cfg);
    for (file_path, content) in files_to_update {
        if file_path.exists() {
            let rel = file_path.strip_prefix(path).unwrap_or(&file_path);
            eprintln!("Replacing {}", rel.display());
        }
        if let Some(parent) = file_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let _ = fs::write(&file_path, content);
    }
}

fn get_updatable_files(_path: &Path, cfg: &GrammarConfig) -> Vec<(PathBuf, String)> {
    Vec::new()
}

fn parse_ts_json(content: &str) -> Option<GrammarConfig> {
    let mut cfg = GrammarConfig::default();
    cfg.name = json_find_string(content, "name").unwrap_or_default();
    cfg.version = extract_metadata_version(content).unwrap_or_default();
    Some(cfg)
}

fn format_config_json(cfg: &GrammarConfig) -> String {
    let ft_json: String = cfg.file_types
        .iter()
        .map(|s| format!("    \"{}\"", s))
        .collect::<Vec<_>>()
        .join(",\n");

    format!(
        "{{\n  \"name\": \"{}\",\n  \"camelcase\": \"{}\",\n  \"title\": \"{}\",\n  \"description\": \"{}\",\n  \"repository\": \"{}\",\n  \"funding\": \"{}\",\n  \"scope\": \"{}\",\n  \"file_types\": [\n{}\n  ],\n  \"version\": \"{}\",\n  \"license\": \"{}\",\n  \"author\": \"{}\",\n  \"email\": \"{}\",\n  \"url\": \"{}\",\n  \"namespace\": \"{}\",\n  \"bindings\": {{\n    \"c\": {},\n    \"go\": {},\n    \"java\": {},\n    \"node\": {},\n    \"python\": {},\n    \"rust\": {},\n    \"swift\": {},\n    \"zig\": {}\n  }}\n}}",
        cfg.name, cfg.camelcase, cfg.title, cfg.description,
        cfg.repository, cfg.funding, cfg.scope, ft_json,
        cfg.version, cfg.license,
        cfg.author_name, cfg.author_email, cfg.author_url, cfg.namespace,
        cfg.bindings_c, cfg.bindings_go, cfg.bindings_java, cfg.bindings_node,
        cfg.bindings_python, cfg.bindings_rust, cfg.bindings_swift, cfg.bindings_zig,
    )
}

fn write_grammar_files(path: &Path, cfg: &GrammarConfig) {
    let _ = fs::create_dir_all(path);

    // Write tree-sitter.json
    let ts_json = generate_ts_json(cfg);
    let ts_json_path = path.join("tree-sitter.json");
    let _ = fs::write(&ts_json_path, ts_json);

    // Write grammar.js
    let grammar_js = generate_grammar_js(cfg);
    let grammar_js_path = path.join("grammar.js");
    if !grammar_js_path.exists() {
        let _ = fs::write(&grammar_js_path, grammar_js);
    }

    // Write other files based on bindings
    write_all_template_files(path, cfg);
}

