// ===== Init command (interactive TUI) =====

fn cmd_init(args: &[String]) {
    if !is_tty(0) {
        eprint_error("IO error: not a terminal");
        process::exit(1);
    }

    let mut grammar_path: Option<PathBuf> = None;
    let mut update = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-u" | "--update" => {
                update = true;
            }
            "-p" | "--grammar-path" => {
                i += 1;
                if i < args.len() {
                    grammar_path = Some(PathBuf::from(&args[i]));
                }
            }
            s if s.starts_with("--grammar-path=") => {
                grammar_path = Some(PathBuf::from(s.strip_prefix("--grammar-path=").unwrap()));
            }
            _ => {}
        }
        i += 1;
    }

    let path = grammar_path.unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
    let ts_json_path = path.join("tree-sitter.json");

    if ts_json_path.exists() && !update {
        // Already initialized - do nothing
        return;
    }

    if update && !ts_json_path.exists() {
        eprint_error(&format!(
            "No such file or directory (os error 2) ({})",
            ts_json_path.display()
        ));
        process::exit(1);
    }

    if update {
        // Read existing config and regenerate files
        do_init_update(&path, &ts_json_path);
        return;
    }

    // Interactive prompts
    let config = run_init_prompts(&path);

    if let Some(cfg) = config {
        // Write tree-sitter.json
        write_grammar_files(&path, &cfg);
    }
}

