fn camelcase(s: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;
    for ch in s.chars() {
        if ch == '-' || ch == '_' {
            capitalize_next = true;
        } else if capitalize_next {
            result.extend(ch.to_uppercase());
            capitalize_next = false;
        } else {
            result.push(ch);
        }
    }
    result
}

fn run_init_prompts(path: &Path) -> Option<GrammarConfig> {
    use std::io::{BufRead, Write};

    let stdin = io::stdin();
    let stderr = io::stderr();

    let mut cfg = GrammarConfig::default();

    // Parser name
    cfg.name = prompt_text("Parser name", None)?;

    // CamelCase name
    let default_camel = camelcase(&cfg.name);
    cfg.camelcase = prompt_text_with_default("CamelCase name", &default_camel)?;

    // Title
    cfg.title = prompt_text_with_default("Title (human-readable name)", &cfg.camelcase.clone())?;

    // Description
    let default_desc = format!("{} grammar for tree-sitter", cfg.camelcase);
    cfg.description = prompt_text_with_default("Description", &default_desc)?;

    // Repository URL
    let default_repo = format!("https://github.com/tree-sitter/tree-sitter-{}", cfg.name);
    cfg.repository = prompt_text_with_default("Repository URL", &default_repo)?;

    // Funding URL
    cfg.funding = prompt_text_optional("Funding URL")?;

    // TextMate scope
    let default_scope = format!("source.{}", cfg.name);
    cfg.scope = prompt_text_with_default("TextMate scope", &default_scope)?;

    // File types
    let default_ft = cfg.name.clone();
    let ft_str = prompt_text_with_default("File types (space-separated)", &default_ft)?;
    cfg.file_types = ft_str.split_whitespace().map(|s| s.to_string()).collect();
    if cfg.file_types.is_empty() {
        cfg.file_types = vec![cfg.name.clone()];
    }

    // Version
    cfg.version = prompt_text_with_default("Version", "0.1.0")?;

    // License
    cfg.license = prompt_text_with_default("License", "MIT")?;

    // Author name
    cfg.author_name = prompt_text_optional("Author name")?;

    // Author email
    cfg.author_email = prompt_text_optional("Author email")?;

    // Author URL
    cfg.author_url = prompt_text_optional("Author URL")?;

    // Package namespace
    cfg.namespace = prompt_text_with_default("Package namespace", "io.github.tree-sitter")?;

    // Bindings multi-select
    let bindings = prompt_bindings()?;
    cfg.bindings_c = bindings.contains(&"c");
    cfg.bindings_go = bindings.contains(&"go");
    cfg.bindings_java = bindings.contains(&"java");
    cfg.bindings_node = bindings.contains(&"node");
    cfg.bindings_python = bindings.contains(&"python");
    cfg.bindings_rust = bindings.contains(&"rust");
    cfg.bindings_swift = bindings.contains(&"swift");
    cfg.bindings_zig = bindings.contains(&"zig");

    // Show current config
    let binding_list: Vec<&str> = ["c", "go", "java", "node", "python", "rust", "swift", "zig"]
        .iter()
        .filter(|&&b| match b {
            "c" => cfg.bindings_c,
            "go" => cfg.bindings_go,
            "java" => cfg.bindings_java,
            "node" => cfg.bindings_node,
            "python" => cfg.bindings_python,
            "rust" => cfg.bindings_rust,
            "swift" => cfg.bindings_swift,
            "zig" => cfg.bindings_zig,
            _ => false,
        })
        .copied()
        .collect();

    let binding_str = binding_list.join(", ");
    eprint!("Bindings: {}\r\n", binding_str);

    // Show config JSON
    let json = format_config_json(&cfg);
    eprint!("Your current configuration:\r\n{}\r\n", json);

    // Confirm
    let confirmed = prompt_confirm("Does the config above look correct?")?;
    if !confirmed {
        return None;
    }

    Some(cfg)
}

fn prompt_text(question: &str, default: Option<&str>) -> Option<String> {
    let stderr = io::stderr();
    let mut se = stderr.lock();

    // Show prompt: \033[33m?\033[0m \033[1mQuestion\033[0m \033[38;5;8m›\033[0m
    if let Some(def) = default {
        write!(se, "\x1b[33m?\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m({})\x1b[0m \x1b[38;5;8m\u{203A}\x1b[0m ").ok()?;
    } else {
        write!(se, "\x1b[33m?\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m\u{203A}\x1b[0m ").ok()?;
    }
    se.flush().ok()?;
    drop(se);

    let mut input = String::new();
    io::stdin().read_line(&mut input).ok()?;
    let input = input.trim_end_matches('\n').trim_end_matches('\r').to_string();

    let result = if input.is_empty() {
        default.map(|s| s.to_string()).unwrap_or_default()
    } else {
        input
    };

    // Print completion: \r\033[2K\033[32m✔\033[0m \033[1mQuestion\033[0m \033[38;5;8m·\033[0m \033[32mresult\033[0m
    let stderr = io::stderr();
    let mut se = stderr.lock();
    write!(se, "\r\x1b[2K\x1b[32m\u{2714}\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m\u{00B7}\x1b[0m \x1b[32m{}\x1b[0m\r\n", question, result).ok()?;
    se.flush().ok()?;

    Some(result)
}

