fn prompt_confirm(question: &str) -> Option<bool> {
    let stderr = io::stderr();
    let mut se = stderr.lock();

    write!(se, "\x1b[33m?\x1b[0m \x1b[1m{}\x1b[0m (y/n) \x1b[38;5;8m\u{203A}\x1b[0m ").ok()?;
    se.flush().ok()?;
    drop(se);

    let mut input = String::new();
    io::stdin().read_line(&mut input).ok()?;
    let input = input.trim_end_matches('\n').trim_end_matches('\r').trim().to_lowercase();

    let result = input == "y" || input == "yes";
    let result_str = if result { "yes" } else { "no" };

    let stderr = io::stderr();
    let mut se = stderr.lock();
    write!(se, "\r\x1b[2K\x1b[32m\u{2714}\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m\u{00B7}\x1b[0m \x1b[32m{}\x1b[0m\r\n", question, result_str).ok()?;
    se.flush().ok()?;

    Some(result)
}

struct MultiSelect {
    options: Vec<(&'static str, bool)>,
    cursor: usize,
}

fn prompt_bindings() -> Option<Vec<&'static str>> {
    // Show multi-select with default selections
    let options: Vec<(&str, bool)> = vec![
        ("c", true),
        ("go", true),
        ("java", false),
        ("node", true),
        ("python", true),
        ("rust", true),
        ("swift", true),
        ("zig", false),
    ];

    use std::os::unix::io::AsRawFd;

    // Set raw mode for input
    let stdin_fd = 0;
    let mut old_termios = unsafe { std::mem::zeroed::<libc_termios>() };
    unsafe { tcgetattr(stdin_fd, &mut old_termios) };

    let mut new_termios = old_termios;
    // Set raw mode: no echo, no line buffering
    unsafe {
        cfmakeraw(&mut new_termios);
    }
    unsafe { tcsetattr(stdin_fd, TCSANOW, &new_termios) };

    let stderr = io::stderr();
    let mut se = stderr.lock();

    // Hide cursor
    write!(se, "\x1b[?25l").ok()?;

    let mut selected = options.clone();
    let mut cursor: usize = 0;

    // Draw initial state
    let header = "Bindings:";
    write!(se, "{}\r\n", header).ok()?;
    for (i, (name, checked)) in selected.iter().enumerate() {
        let prefix = if i == cursor { "> " } else { "  " };
        let check = if *checked { "[x]" } else { "[ ]" };
        write!(se, "{}{} {}\r\n", prefix, check, name).ok()?;
    }
    se.flush().ok()?;

    // Process input
    loop {
        drop(se);
        let mut buf = [0u8; 4];
        let n = unsafe { libc_read(stdin_fd, buf.as_mut_ptr(), buf.len()) };

        let stderr2 = io::stderr();
        let mut se2 = stderr2.lock();

        if n <= 0 {
            break;
        }

        let key = &buf[..n as usize];

        // Move cursor up to redraw
        let num_lines = selected.len() + 1; // header + options
        write!(se2, "\x1b[{}A", num_lines).ok()?;

        let stop = match key {
            b"\r" | b"\n" => true, // Enter
            b"\x1b[A" => { // Up arrow
                if cursor > 0 { cursor -= 1; }
                false
            }
            b"\x1b[B" => { // Down arrow
                if cursor < selected.len() - 1 { cursor += 1; }
                false
            }
            b" " => { // Space - toggle
                selected[cursor].1 = !selected[cursor].1;
                false
            }
            _ => false,
        };

        // Redraw
        write!(se2, "\x1b[2K{}\r\n", header).ok()?;
        for (i, (name, checked)) in selected.iter().enumerate() {
            let prefix = if i == cursor { "> " } else { "  " };
            let check = if *checked { "[x]" } else { "[ ]" };
            write!(se2, "\x1b[2K{}{} {}\r\n", prefix, check, name).ok()?;
        }
        se2.flush().ok()?;

        if stop {
            se = se2;
            break;
        }
        se = se2;
    }

    // Restore terminal
    unsafe { tcsetattr(stdin_fd, TCSANOW, &old_termios) };

    // Show cursor
    write!(se, "\x1b[?25h").ok()?;

    // Collect selected bindings
    let result: Vec<&'static str> = selected
        .iter()
        .filter(|(_, checked)| *checked)
        .map(|(name, _)| *name)
        .collect();

    // Clear the multi-select display and show summary
    let num_lines = selected.len() + 1;
    write!(se, "\x1b[{}A", num_lines).ok()?;
    write!(se, "\x1b[2K").ok()?;
    let summary = result.join(", ");
    write!(se, "Bindings: {}\r\n", summary).ok()?;
    // Clear remaining lines
    for _ in 0..selected.len() {
        write!(se, "\x1b[2K\r\n").ok()?;
    }
    write!(se, "\x1b[{}A", selected.len()).ok()?;
    se.flush().ok()?;

    Some(result)
}

