unsafe extern "C" {{
    fn tree_sitter_{under}() -> *const ();
}}

/// The tree-sitter [`LanguageFn`] for this grammar.
pub const LANGUAGE: LanguageFn = unsafe {{ LanguageFn::from_raw(tree_sitter_{under}) }};

/// The content of the [`node-types.json`] file for this grammar.
