fn write_all_template_files(path: &Path, cfg: &GrammarConfig) {
    let name = &cfg.name;
    let camel = &cfg.camelcase;
    let title = &cfg.title;
    let desc = &cfg.description;
    let repo = &cfg.repository;
    let ver = &cfg.version;
    let lic = &cfg.license;
    let author = &cfg.author_name;
    let email = &cfg.author_email;
    let url = &cfg.author_url;
    let ns = &cfg.namespace;

    // .editorconfig
    write_file(path, ".editorconfig", EDITORCONFIG);

    // .gitattributes
    write_file(path, ".gitattributes", GITATTRIBUTES);

    // .gitignore
    write_file(path, ".gitignore", GITIGNORE);

    // Makefile
    let makefile = generate_makefile(cfg);
    write_file(path, "Makefile", &makefile);

    // CMakeLists.txt
    let cmake = generate_cmake(cfg);
    write_file(path, "CMakeLists.txt", &cmake);

    // Cargo.toml
    let cargo_toml = generate_cargo_toml(cfg);
    write_file(path, "Cargo.toml", &cargo_toml);

    // package.json
    let pkg_json = generate_package_json(cfg);
    write_file(path, "package.json", &pkg_json);

    // pyproject.toml
    let pyproject = generate_pyproject(cfg);
    write_file(path, "pyproject.toml", &pyproject);

    // setup.py
    let setup_py = generate_setup_py(cfg);
    write_file(path, "setup.py", &setup_py);

    // Package.swift
    let pkg_swift = generate_package_swift(cfg);
    write_file(path, "Package.swift", &pkg_swift);

    // binding.gyp
    let binding_gyp = generate_binding_gyp(cfg);
    write_file(path, "binding.gyp", &binding_gyp);

    // go.mod
    let go_mod = generate_go_mod(cfg);
    write_file(path, "go.mod", &go_mod);

    // Bindings
    if cfg.bindings_c {
        write_c_bindings(path, cfg);
    }
    if cfg.bindings_go {
        write_go_bindings(path, cfg);
    }
    if cfg.bindings_node {
        write_node_bindings(path, cfg);
    }
    if cfg.bindings_python {
        write_python_bindings(path, cfg);
    }
    if cfg.bindings_rust {
        write_rust_bindings(path, cfg);
    }
    if cfg.bindings_swift {
        write_swift_bindings(path, cfg);
    }
}

fn write_file(base: &Path, rel: &str, content: &str) {
    let path = base.join(rel);
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let _ = fs::write(&path, content);
}

