fn generate_makefile(cfg: &GrammarConfig) -> String {
    format!(
        "LANGUAGE_NAME := tree-sitter-{name}
HOMEPAGE_URL := {repo}
VERSION := {ver}

# repository
SRC_DIR := src

TS ?= tree-sitter

# install directory layout
PREFIX ?= /usr/local
DATADIR ?= $(PREFIX)/share
INCLUDEDIR ?= $(PREFIX)/include
LIBDIR ?= $(PREFIX)/lib
BINDIR ?= $(PREFIX)/bin
PCLIBDIR ?= $(LIBDIR)/pkgconfig

# source/object files
PARSER := $(SRC_DIR)/parser.c
EXTRAS := $(filter-out $(PARSER),$(wildcard $(SRC_DIR)/*.c))
OBJS := $(patsubst %.c,%.o,$(PARSER) $(EXTRAS))

# flags
ARFLAGS ?= rcs
override CFLAGS += -I$(SRC_DIR) -std=c11 -fPIC

# ABI versioning
SONAME_MAJOR = $(shell sed -n 's/\#define LANGUAGE_VERSION //p' $(PARSER))
SONAME_MINOR = $(word 1,$(subst ., ,$(VERSION)))

# OS-specific bits
MACHINE := $(shell $(CC) -dumpmachine)

ifneq ($(findstring darwin,$(MACHINE)),)
	SOEXT = dylib
	SOEXTVER_MAJOR = $(SONAME_MAJOR).$(SOEXT)
	SOEXTVER = $(SONAME_MAJOR).$(SONAME_MINOR).$(SOEXT)
	LINKSHARED = -dynamiclib -Wl,-install_name,$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXTVER),-rpath,@executable_path/../Frameworks
else ifneq ($(findstring mingw32,$(MACHINE)),)
	SOEXT = dll
	SOEXTVER_MAJOR = $(SOEXT)
	SOEXTVER = $(SOEXT)
	LINKSHARED = -shared -Wl,--no-undefined
else
	SOEXT = so
	SOEXTVER_MAJOR = $(SOEXT).$(SONAME_MAJOR)
	SOEXTVER = $(SOEXT).$(SONAME_MAJOR).$(SONAME_MINOR)
	LINKSHARED = -shared -Wl,-soname,lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR)
endif

all: lib$(LANGUAGE_NAME).$(SOEXTVER)

$(PARSER): grammar.js
	$(TS) generate --no-parser $<

lib$(LANGUAGE_NAME).$(SOEXTVER): $(OBJS)
	$(CC) $(LDFLAGS) $(LINKSHARED) $^ $(LDLIBS) -o $@
	iln -sf lib$(LANGUAGE_NAME).$(SOEXTVER) lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR) 2>/dev/null || true
	ln -sf lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR) lib$(LANGUAGE_NAME).$(SOEXT) 2>/dev/null || true

%.o: %.c
	$(CC) -c $(CFLAGS) $< -o $@

install: all
	install -d '$(DESTDIR)$(LIBDIR)'
	install -m755 lib$(LANGUAGE_NAME).$(SOEXTVER) '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXTVER)'
	ln -sf 'lib$(LANGUAGE_NAME).$(SOEXTVER)' '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR)'
	ln -sf 'lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR)' '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXT)'
	install -d '$(DESTDIR)$(INCLUDEDIR)/tree_sitter'
	install -m644 bindings/c/tree_sitter/$(LANGUAGE_NAME).h '$(DESTDIR)$(INCLUDEDIR)/tree_sitter/$(LANGUAGE_NAME).h'
	install -d '$(DESTDIR)$(PCLIBDIR)'
	install -m644 bindings/c/$(LANGUAGE_NAME).pc.in '$(DESTDIR)$(PCLIBDIR)/$(LANGUAGE_NAME).pc'

sed 's|@CMAKE_INSTALL_PREFIX@|$(PREFIX)|g;s|@CMAKE_INSTALL_LIBDIR@|$(LIBDIR)|g;s|@CMAKE_INSTALL_INCLUDEDIR@|$(INCLUDEDIR)|g;s|@PROJECT_DESCRIPTION@|$(DESCRIPTION)|g;s|@PROJECT_HOMEPAGE_URL@|$(HOMEPAGE_URL)|g;s|@PROJECT_VERSION@|$(VERSION)|g' \
bindings/c/$(LANGUAGE_NAME).pc.in > '$(DESTDIR)$(PCLIBDIR)/$(LANGUAGE_NAME).pc'

uninstall:
	$(RM) '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXTVER)'
	$(RM) '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXTVER_MAJOR)'
	$(RM) '$(DESTDIR)$(LIBDIR)/lib$(LANGUAGE_NAME).$(SOEXT)'
	$(RM) '$(DESTDIR)$(INCLUDEDIR)/tree_sitter/$(LANGUAGE_NAME).h'
	$(RM) '$(DESTDIR)$(PCLIBDIR)/$(LANGUAGE_NAME).pc'

clean:
	$(RM) $(OBJS)
	$(RM) lib$(LANGUAGE_NAME).$(SOEXTVER)

.PHONY: all install uninstall clean
",
        name = cfg.name,
        repo = cfg.repository,
        ver = cfg.version,
    )
}

