fn write_prompt(question: &str, default: Option<&str>) {
    let stderr = io::stderr();
    let mut se = stderr.lock();
    if let Some(def) = default {
        let _ = write!(se, "\x1b[33m?\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m({})\x1b[0m \x1b[38;5;8m\u{203A}\x1b[0m ", question, def);
