    }
    let _ = se.flush();
}

fn write_completed(question: &str, result: &str) {
    let stderr = io::stderr();
    let mut se = stderr.lock();
    let _ = write!(se, "\r\x1b[2K\x1b[32m\u{2714}\x1b[0m \x1b[1m{}\x1b[0m \x1b[38;5;8m\u{00B7}\x1b[0m \x1b[32m{}\x1b[0m\r\n", question, result);
    let _ = se.flush();
}

fn read_line_stdin() -> Option<String> {
    let mut input = String::new();
    match io::stdin().read_line(&mut input) {
        Ok(_) => Some(input.trim_end_matches('\n').trim_end_matches('\r').to_string()),
        Err(_) => None,
    }
}

fn prompt_text(question: &str, _default: Option<&str>) -> Option<String> {
    write_prompt(question, None);
    let input = read_line_stdin()?;
    write_completed(question, &input);
    Some(input)
}

fn prompt_text_with_default(question: &str, default: &str) -> Option<String> {
    write_prompt(question, Some(default));
    let input = read_line_stdin()?;
    let result = if input.is_empty() {
        default.to_string()
    } else {
        input
    };
    write_completed(question, &result);
    Some(result)
}

