    for (i, &(name, checked)) in selected.iter().enumerate() {
        let prefix = if i == cursor { "> " } else { "  " };
        let check = if checked { "[x]" } else { "[ ]" };
        let _ = write!(se, "{}{} {}\r\n", prefix, check, name);
    }
    let _ = se.flush();

    loop {
        drop(se);

        let mut buf = [0u8; 8];
        let n = unsafe { read(stdin_fd, buf.as_mut_ptr(), buf.len()) };

        let stderr2 = io::stderr();
        let mut se2 = stderr2.lock();

        if n <= 0 {
            // Restore terminal and exit
            unsafe { tcsetattr(stdin_fd, TCSANOW, &old_termios) };
            let _ = write!(se2, "\x1b[?25h");
            let _ = se2.flush();
            return None;
        }

        let key = &buf[..n as usize];

        // Move cursor up to redraw
        let num_lines = selected.len() + 1;
        let _ = write!(se2, "\x1b[{}A", num_lines);

        let stop = match key {
            b"\r" | b"\n" => true,
            b"\x1b[A" => { if cursor > 0 { cursor -= 1; } false }
            b"\x1b[B" => { if cursor + 1 < selected.len() { cursor += 1; } false }
            b" " => { selected[cursor].1 = !selected[cursor].1; false }
            _ => false,
        };

        // Redraw
        let _ = write!(se2, "\x1b[2KBindings:\r\n");
        for (i, &(name, checked)) in selected.iter().enumerate() {
            let prefix = if i == cursor { "> " } else { "  " };
            let check = if checked { "[x]" } else { "[ ]" };
            let _ = write!(se2, "\x1b[2K{}{} {}\r\n", prefix, check, name);
        }
        let _ = se2.flush();

        se = se2;

        if stop {
            break;
        }
    }

    // Restore terminal
    unsafe { tcsetattr(stdin_fd, TCSANOW, &old_termios) };
    let _ = write!(se, "\x1b[?25h");

    // Collect results
    let result: Vec<&'static str> = selected
        .iter()
        .filter(|(_, checked)| *checked)
        .map(|(name, _)| *name)
        .collect();

    // Clear the multi-select and show summary
    let num_lines = selected.len() + 1;
    let _ = write!(se, "\x1b[{}A", num_lines);
    let summary = result.join(", ");
    let _ = write!(se, "\x1b[2KBindings: {}\r\n", summary);
    for _ in 0..selected.len() {
        let _ = write!(se, "\x1b[2K\r\n");
    }
    let _ = write!(se, "\x1b[{}A", selected.len());
    let _ = se.flush();

    Some(result)
}

